mapper.select:
select 'APP_CONFIG' resourceType,id resourceId from p_app_config where id=#{configId}
union all select 'AVATAR_VERSION',avatar_version_id from p_app_config where id=#{configId}
union all select 'VOICE_VERSION',voice_version_id from p_app_config where id=#{configId}
union all select 'RELAY_VERSION',llm_relay_version_id from p_app_config where id=#{configId} and llm_relay_version_id is not null
union all select 'RELAY_VERSION',asr_relay_version_id from p_app_config where id=#{configId} and asr_relay_version_id is not null and asr_relay_version_id != llm_relay_version_id
union all select 'SKILL_VERSION',skill_version_id from p_app_skill where app_config_id=#{configId} and enabled=1
